import boto3
import os
import json
import uuid
from typing import List, Dict, Any

def publish_batch_messages(queue_url: str, messages: List[Dict[str, Any]]):
    """
    Publishes a batch of messages with attributes to an Amazon SQS queue.

    Args:
        queue_url (str): The URL of the Amazon SQS queue.
        messages (List[Dict[str, Any]]): A list of message objects. Each object
            should be a dictionary with a 'body' key and an optional 'attributes' key.
            e.g., [{'body': {'key': 'value'}, 'attributes': {'attr_key': 'attr_value'}}]

    Returns:
        The response from the SQS send_message_batch API call, or None on error.
    """
    # Boto3 will use credentials from environment variables (AWS_ACCESS_KEY_ID,
    # AWS_SECRET_ACCESS_KEY) or an IAM role. The AWS_REGION should also be set.
    sqs_client = boto3.client("sqs")

    entries = []
    for message in messages:
        # Each message in a batch request must have a unique Id.
        entry_id = str(uuid.uuid4())

        message_attributes = {}
        if 'attributes' in message and message['attributes']:
            for key, value in message['attributes'].items():
                message_attributes[key] = {
                    'DataType': 'String',
                    'StringValue': str(value)
                }

        entry = {
            'Id': entry_id,
            'MessageBody': json.dumps(message.get('body', {}))
        }

        if message_attributes:
            entry['MessageAttributes'] = message_attributes

        entries.append(entry)

    if not entries:
        print("No messages to send.")
        return None

    try:
        print(f"Sending {len(entries)} messages to {queue_url}...")
        response = sqs_client.send_message_batch(
            QueueUrl=queue_url,
            Entries=entries
        )
        print("Batch send API call successful.")

        if 'Successful' in response:
            for msg_meta in response['Successful']:
                print(f"  Successfully sent message ID: {msg_meta['Id']} -> SQS MessageId: {msg_meta['MessageId']}")

        if 'Failed' in response and response['Failed']:
            print("  Some messages failed to send:")
            for msg_meta in response['Failed']:
                print(f"    Failed message ID: {msg_meta['Id']}, Code: {msg_meta['Code']}")

        return response

    except sqs_client.exceptions.ClientError as e:
        print(f"An error occurred while sending messages: {e}")
        return None
